 void welcome(){directoryReady=false;generation++;boolean reset=page!=null||preview!=null;if(page!=null)page.dispose();if(preview!=null)preview.dispose();if(reset)build();current=null;history.clear();query="";category="Todos";searchVisible=false;prefs.edit().remove("current").apply();rows.clear();selected.clear();selectMode=false;search.setVisibility(View.GONE);address.setText("Meu dispositivo");body.removeAllViews();TextView heading=text("Meu dispositivo",19);heading.setTypeface(null,Typeface.BOLD);heading.setPadding(dp(10),dp(10),dp(10),dp(10));heading.setBackground(bevel(false));body.addView(heading);ScrollView scroll=new ScrollView(this);LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(12),dp(12),dp(12),dp(12));scroll.addView(content);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));new RetroHome(this).populate(content,generation);status.setText("Meu dispositivo • pronto para explorar");updateActions();}
