 void chooseTree(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(i,100);}
 void requestAll(){if(Build.VERSION.SDK_INT>=30){if(Environment.isExternalStorageManager()){openLocal();return;}new RetroDialog(this).setTitle("Acesso aos arquivos compartilhados").setMessage("Permite explorar e organizar o armazenamento compartilhado. Não libera dados privados dos outros apps. Você pode continuar usando apenas pastas escolhidas.").setPositiveButton("Abrir configurações",(d,w)->{try{startActivityForResult(new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+getPackageName())),101);}catch(Exception e){startActivityForResult(new Intent(Settings.ACTION_MANAGE_ALL_FILES_ACCESS_PERMISSION),101);}}).setNegativeButton("Agora não",null).show();}else chooseTree();}
 void openLocal(){try{navigate(engine.local(Environment.getExternalStorageDirectory()));}catch(Exception e){error(e);}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==101&&Build.VERSION.SDK_INT>=30&&Environment.isExternalStorageManager())openLocal();if(request==100&&result==RESULT_OK&&data!=null){try{Uri u=data.getData();int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if((flags&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)!=0)getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);else getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);FileEngine.Node n=engine.tree(u);Set<String> roots=new HashSet<>(prefs.getStringSet("roots",new HashSet<>()));roots.add(n.uri.toString());prefs.edit().putStringSet("roots",roots).apply();navigate(n);}catch(Exception e){error(e);}}}
 void navigate(FileEngine.Node n){boolean reset=page!=null||preview!=null;if(page!=null)page.dispose();if(preview!=null)preview.dispose();if(reset)build();if(!n.directory){load();if(kind(n).equals("Imagens"))showPreview(n);else open(n,false);return;}if(current!=null)history.push(current);current=n;selected.clear();selectMode=false;query="";search.setText("");category="Todos";prefs.edit().putString("current",n.file!=null?Uri.fromFile(n.file).toString():n.uri.toString()).apply();load();}
 void load(){if(preview!=null||page!=null)return;if(!busy)engine.resetCancellation();if(current==null){welcome();return;}directoryReady=false;final int token=++generation;FileEngine.Node dir=current;address.setText(dir.file!=null?displayPath(dir.file):dir.name+" • pasta autorizada");address.setContentDescription("Local atual: "+address.getText()+". Escolher outro local");updateActions();status.setText("Lendo pasta…");body.removeAllViews();TextView loading=text("Lendo pasta…",16);loading.setPadding(dp(16),dp(16),dp(16),dp(16));body.addView(loading);rows.clear();updateActions();IO.execute(()->{try{List<FileEngine.Node> found=engine.list(dir);runOnUiThread(()->{if(token!=generation||isFinishing()||isDestroyed())return;directoryReady=true;rows=new ArrayList<>(found);selected.keySet().retainAll(found.stream().map(n->n.id).collect(java.util.stream.Collectors.toList()));render();});}catch(Exception e){runOnUiThread(()->{if(token!=generation||isFinishing()||isDestroyed())return;rows.clear();selected.clear();selectMode=false;updateActions();body.removeAllViews();ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);LinearLayout state=new LinearLayout(this);state.setOrientation(LinearLayout.VERTICAL);state.setGravity(Gravity.CENTER);state.setPadding(dp(20),dp(20),dp(20),dp(20));scroll.addView(state);state.addView(symbol("computer",48),new LinearLayout.LayoutParams(dp(48),dp(48)));TextView t=text("Acesso removido ou volume desconectado",18);t.setGravity(Gravity.CENTER);state.addView(t);TextView detail=text("Reconecte o volume ou escolha novamente a pasta no Android. Seus favoritos foram mantidos.",14);detail.setGravity(Gravity.CENTER);detail.setPadding(0,dp(12),0,dp(12));state.addView(detail);state.addView(button("Selecionar pasta novamente",()->chooseTree()));state.addView(button("Meu dispositivo",()->welcome()));body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));status.setText("Local indisponível");});}});}
 ArrayList<FileEngine.Node> filtered(){ArrayList<FileEngine.Node> result=new ArrayList<>();for(FileEngine.Node n:rows){if(!hidden&&n.name.startsWith("."))continue;if(!n.name.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;if(!category.equals("Todos")&&(n.directory||!kind(n).equals(category)))continue;result.add(n);}result.sort((a,b)->{if(foldersFirst&&a.directory!=b.directory)return a.directory?-1:1;return switch(sort){case 1->Long.compare(b.modified,a.modified);case 2->Long.compare(b.size,a.size);default->a.name.compareToIgnoreCase(b.name);};});return result;}
 String kind(FileEngine.Node n){String m=n.mime==null?mime(n.name):n.mime;if(m.startsWith("image/"))return "Imagens";if(m.startsWith("video/"))return "Vídeos";if(m.startsWith("audio/"))return "Áudios";return "Documentos";}
