 void tap(FileEngine.Node n){if(selectMode){toggle(n);return;}if(n.directory)navigate(n);else if(kind(n).equals("Imagens"))showPreview(n);else open(n,false);}
 void toggle(FileEngine.Node n){selectMode=true;if(selected.containsKey(n.id))selected.remove(n.id);else selected.put(n.id,n);render();}
 void showPreview(FileEngine.Node n){if(page!=null){page.dispose();build();}if(preview!=null)preview.dispose();preview=new RetroPreview(this,n);preview.show();}
 void back(){if(page!=null){page.close();return;}if(preview!=null){preview.close();return;}if(selectMode){selectMode=false;selected.clear();render();}else if(!history.isEmpty()){current=history.pop();query="";category="Todos";search.setText("");prefs.edit().putString("current",current.file!=null?Uri.fromFile(current.file).toString():current.uri.toString()).apply();load();}else if(current!=null){current=null;welcome();}else finish();}
