 void menuPopup(View anchor,String[] labels,boolean[] allowed,java.util.function.IntConsumer action){if(compact()&&!anchor.isAttachedToWindow())anchor=fileButton;ScrollView scroll=new ScrollView(this);LinearLayout options=new LinearLayout(this);options.setOrientation(LinearLayout.VERTICAL);options.setPadding(dp(3),dp(3),dp(3),dp(3));options.setBackground(bevel(false));scroll.addView(options);PopupWindow popup=new PopupWindow(scroll,Math.min(getResources().getDisplayMetrics().widthPixels-dp(24),dp(300)),WindowManager.LayoutParams.WRAP_CONTENT,true);popup.setBackgroundDrawable(bevel(false));popup.setOutsideTouchable(true);popup.setElevation(dp(4));for(int i=0;i<labels.length;i++){final int at=i;String label=labels[i];if(label.equals("---")){View line=new View(this);line.setBackgroundColor(dark?0xff777777:0xff808080);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(1));lp.setMargins(dp(28),dp(3),dp(3),dp(3));options.addView(line,lp);continue;}Button option=button(label.replace("✓ ",""),()->{popup.dismiss();action.accept(at);});option.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);StateListDrawable states=new StateListDrawable();states.addState(new int[]{android.R.attr.state_pressed},new ColorDrawable(blue));states.addState(new int[]{android.R.attr.state_focused},new ColorDrawable(blue));states.addState(new int[]{},new ColorDrawable(bg));option.setBackground(states);option.setOnFocusChangeListener(null);option.setTextColor(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_pressed},new int[]{android.R.attr.state_focused},new int[]{}},new int[]{Color.WHITE,Color.WHITE,fg}));String icon=label.startsWith("✓ ")?"check":label.startsWith("Copiar")?"copy":label.startsWith("Mover")?"move":label.startsWith("Excluir")?"delete":label.contains("favoritos")?"star":label.contains("pasta")?"folder":label.contains("Ícones")?"grid":label.contains("Lista")?"list":label.contains("Transfer")?"transfer":"doc";RetroUi.Symbol symbol=new RetroUi.Symbol(icon,dark);symbol.setBounds(0,0,dp(18),dp(18));option.setCompoundDrawables(symbol,null,null,null);option.setCompoundDrawablePadding(dp(12));if(allowed!=null)enabled(option,allowed[i]);option.setPadding(dp(8),dp(8),dp(8),dp(8));options.addView(option,new LinearLayout.LayoutParams(-1,-2));}options.measure(View.MeasureSpec.makeMeasureSpec(popup.getWidth(),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));popup.setHeight(Math.min(options.getMeasuredHeight(),getResources().getDisplayMetrics().heightPixels*2/3));popup.showAsDropDown(anchor);}

 void fileMenu(){if(page!=null||preview!=null)return;String[] opts={"Nova pasta…","Selecionar tudo visível","Ações da seleção…","Conectar pasta / SD / USB…","Transferências…","Atualizar pasta"};menuPopup(fileButton,opts,new boolean[]{current!=null&&directoryReady&&current.canCreate&&!busy,current!=null&&!rows.isEmpty(),!selected.isEmpty(),true,true,current!=null},w->{switch(w){case 0->newFolder();case 1->{selectMode=true;for(FileEngine.Node n:filtered())selected.put(n.id,n);render();}case 2->selectionMenu();case 3->chooseTree();case 4->transferStatus();case 5->load();}});}
 void viewMenu(){if(page!=null||preview!=null)return;String[] opts={!gridMode?"✓ Lista":"Lista",gridMode?"✓ Ícones":"Ícones","---","Ordenar…","Categoria nesta pasta…","---",dark?"Tema clássico claro":"Tema clássico escuro",hidden?"✓ Mostrar ocultos":"Mostrar ocultos","Preferências…","Armazenamento…"};menuPopup(viewButton,opts,new boolean[]{true,true,false,current!=null,current!=null,false,true,true,true,current!=null&&directoryReady},w->{switch(w){case 0,1->{gridMode=w==1;prefs.edit().putBoolean("grid",gridMode).apply();render();}case 3->new RetroDialog(this).setTitle("Ordenar por").setItems(new String[]{"Nome","Mais recentes","Maiores arquivos"},(a,b)->{sort=b;render();}).show();case 4->new RetroDialog(this).setTitle("Filtrar pasta atual").setMessage("Este filtro considera somente os itens da pasta atual.").setItems(new String[]{"Todos","Imagens","Vídeos","Áudios","Documentos"},(a,b)->{category=new String[]{"Todos","Imagens","Vídeos","Áudios","Documentos"}[b];render();}).show();case 6->{dark=!dark;prefs.edit().putBoolean("dark",dark).apply();build();load();}case 8->new RetroPages(this).preferences();case 9->{if(current!=null)new RetroCatalog(this).storage(current);}case 7->{hidden=!hidden;prefs.edit().putBoolean("hidden",hidden).apply();render();}}});}

 void locations(){ArrayList<String> names=new ArrayList<>(Arrays.asList("Armazenamento compartilhado","Escolher outra pasta / SD / USB"));ArrayList<String> ids=new ArrayList<>();Set<String> roots=new HashSet<>(prefs.getStringSet("roots",new HashSet<>()));roots.addAll(prefs.getStringSet("favorites",new HashSet<>()));for(String id:roots){try{FileEngine.Node n=from(id);names.add("★ "+n.name);ids.add(id);}catch(Exception ignored){}}new RetroDialog(this).setTitle("Locais e favoritos").setItems(names.toArray(new String[0]),(d,w)->{if(w==0)requestAll();else if(w==1)chooseTree();else try{navigate(from(ids.get(w-2)));}catch(Exception e){error(e);}}).show();}
 FileEngine.Node from(String id)throws IOException{return id.startsWith("file:")?engine.local(new File(Uri.parse(id).getPath())):engine.document(Uri.parse(id));}
 String locationId(FileEngine.Node n){return n.file!=null?Uri.fromFile(n.file).toString():n.uri.toString();}
 void addFavorite(FileEngine.Node n){Set<String> set=new HashSet<>(prefs.getStringSet("favorites",new HashSet<>()));String id=locationId(n);set.add(id);prefs.edit().putStringSet("favorites",set).putString("favorite_name_"+id,n.name).apply();toast("Adicionado aos favoritos");}
 void favorite(){if(current!=null)addFavorite(current);}
 void newFolder(){if(current==null||!directoryReady||busy)return;FileEngine.Node dir=current;input("Nova pasta","",name->operate("Criando pasta",()->{engine.createDirectory(dir,name);return "Pasta criada.";}));}
 interface NameAction{void run(String s);}void input(String title,String value,NameAction action){input(title,value,null,action);}
 void input(String title,String value,String footnote,NameAction action){LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);TextView label=text(title.equals("Nova pasta")?"Nome da pasta:":"Nome:",16);content.addView(label);EditText edit=new EditText(this);edit.setSingleLine();edit.setTextColor(fg);edit.setBackground(bevel(true));edit.setPadding(dp(6),dp(10),dp(6),dp(10));edit.setText(value);edit.setSelectAllOnFocus(true);edit.setContentDescription(label.getText());content.addView(edit,new LinearLayout.LayoutParams(-1,-2));if(footnote!=null){TextView note=text(footnote,14);note.setPadding(0,dp(10),0,0);content.addView(note);}new RetroDialog(this).setTitle(title).setView(content).validatePositive(()->{try{FileEngine.validName(edit.getText().toString().trim());return true;}catch(IOException ex){edit.setError(ex.getMessage());edit.requestFocus();return false;}}).setPositiveButton(title.equals("Nova pasta")?"Criar":"Renomear",(a,b)->action.run(edit.getText().toString().trim())).setNegativeButton("Cancelar",null).show();}
 void renameInput(FileEngine.Node n){int dot=n.directory?-1:n.name.lastIndexOf('.');if(dot<=0)dot=-1;String extension=dot<0?"":n.name.substring(dot);String base=dot<0?n.name:n.name.substring(0,dot);input("Renomear",base,extension.isEmpty()?null:"Extensão: "+extension+"\nO formato do arquivo será mantido.",name->operate("Renomeando",()->{engine.rename(n,name+extension);return "Item renomeado.";}));}
 void selectionMenu(){if(selected.isEmpty()){toast("Selecione um ou mais arquivos primeiro.");return;}ArrayList<FileEngine.Node> items=new ArrayList<>(selected.values());String[] ops={"Copiar para…","Mover para…","Renomear","Propriedades","Compartilhar","Excluir permanentemente","Adicionar aos favoritos"};boolean one=items.size()==1;boolean[] enabledActions={!busy,!busy&&items.stream().allMatch(n->!n.directory&&n.file!=null&&n.canDelete),!busy&&one&&items.get(0).canRename,one,one&&!items.get(0).directory,!busy&&items.stream().allMatch(n->n.canDelete),true};menuPopup(editButton,ops,enabledActions,w->{switch(w){case 0->destination(items,false);case 1->{if(items.stream().anyMatch(n->n.directory)){alert("Movimentação de pastas","Nesta versão, copie a pasta e confira os arquivos antes de excluir a origem. Mover está disponível somente para arquivos.");return;}destination(items,true);}case 2->{if(items.size()!=1){toast("Selecione apenas um item para renomear.");return;}FileEngine.Node n=items.get(0);if(!n.canRename){alert("Renomear indisponível","Este local não oferece renomeação segura nesta versão.");return;}renameInput(n);}case 3->{if(items.size()==1)new RetroPages(this).properties(items.get(0));else alert("Propriedades","Selecione um item para consultar seus metadados.");}case 4->{if(items.size()!=1||items.get(0).directory){toast("Selecione um arquivo para compartilhar.");return;}open(items.get(0),true);}case 6->{for(FileEngine.Node n:items)addFavorite(n);}case 5->new RetroDialog(this).setTitle("Excluir permanentemente?").setMessage(items.size()+" item(ns) em "+(current==null?"local selecionado":current.name)+".\n\n"+items.stream().limit(5).map(n->n.name).reduce("",(a,b)->a+"\n"+b)+"\n\nNão há lixeira nem desfazer. Esta ação não pode ser revertida pelo app.").setPositiveButton("Excluir",(a,b)->operate("Excluindo",()->{int ok=0;for(FileEngine.Node n:items){if(engine.cancelled.get())break;engine.delete(n);ok++;}return ok+" item(ns) excluído(s).";})).setNegativeButton("Cancelar",null).show();}});}
 void destination(ArrayList<FileEngine.Node> items,boolean move){if(current==null||items.isEmpty()||busy)return;pickDestination(current,items,move,new ArrayDeque<>());}
 void pickDestination(FileEngine.Node dir,ArrayList<FileEngine.Node> items,boolean move,ArrayDeque<FileEngine.Node> stack){new RetroTransfers(this).destination(dir,items,move,stack);}
 void pickRoot(ArrayList<FileEngine.Node> items,boolean move){ArrayList<FileEngine.Node> nodes=new ArrayList<>();try{if(Build.VERSION.SDK_INT>=30&&Environment.isExternalStorageManager())nodes.add(engine.local(Environment.getExternalStorageDirectory()));}catch(Exception ignored){}for(String id:prefs.getStringSet("roots",new HashSet<>()))try{nodes.add(from(id));}catch(Exception ignored){}if(nodes.isEmpty()){toast("Conecte uma pasta em Locais primeiro.");return;}new RetroDialog(this).setTitle("Destino").setItems(nodes.stream().map(n->n.name).toArray(String[]::new),(d,w)->pickDestination(nodes.get(w),items,move,new ArrayDeque<>())).show();}
 void transfer(ArrayList<FileEngine.Node> items,FileEngine.Node dest,boolean move,boolean skipExisting){
  if(items.isEmpty()||busy)return;
  String origin=current==null?"":locationId(current);
  operate(move?"Movendo":"Copiando",()->{
   TransferLedger.begin(prefs,dest.name,locationId(dest),origin,items.size(),move);
   int ok=0,skipped=0;StringBuilder issues=new StringBuilder();
   try{for(int index=0;index<items.size();index++){
    FileEngine.Node n=items.get(index);if(engine.cancelled.get())break;
    progress=(move?"Movendo ":"Copiando ")+(index+1)+" de "+items.size();TransferLedger.item(prefs,index,n.name,"Em andamento",dest.name);
    try{
     if(skipExisting&&engine.list(dest).stream().anyMatch(other->other.name.equalsIgnoreCase(n.name))){skipped++;TransferLedger.item(prefs,index,n.name,"Pulado","Nome já existente no destino. Original mantido.");continue;}
     if(dest.file!=null&&!n.directory&&n.size>0){try{android.os.StatFs stat=new android.os.StatFs(dest.file.getPath());if(stat.getAvailableBytes()<n.size)throw new IOException("Espaço insuficiente no destino. Escolha outra pasta ou libere espaço manualmente; nenhum arquivo deste item foi criado.");}catch(IllegalArgumentException unavailable){throw new IOException("Não foi possível consultar o volume de destino.",unavailable);}}
     FileEngine.Node made=engine.copy(n,dest,move);ok++;TransferLedger.item(prefs,index,n.name,"Concluído",(move?"Movido e verificado: ":"Copiado e verificado: ")+made.name);
    }catch(Exception e){String detail=e.getMessage()==null?"Resultado não confirmado; confira origem e destino.":e.getMessage();issues.append("\n").append(n.name).append(": ").append(detail);TransferLedger.item(prefs,index,n.name,"Atenção",detail);if(engine.cancelled.get())break;}
   }}finally{TransferLedger.finish(prefs,engine.cancelled.get());}
   return ok+" de "+items.size()+" concluído(s); "+skipped+" pulado(s)."+(engine.cancelled.get()?" Cancelado.":"")+issues;
  });
 }
 interface Job{String run()throws Exception;}
 void operate(String label,Job job){if(busy){toast("Aguarde ou cancele a operação atual.");return;}busy=true;updateActions();progress=label;activeEngine=engine;engine.resetCancellation();prefs.edit().putBoolean("pending",true).putString("result",label+": resultado ainda não confirmado.").commit();IO.execute(()->{String result;try{result=job.run();}catch(Exception e){result="Operação não concluída. "+e.getMessage()+"\nConfira origem e destino antes de repetir.";}prefs.edit().putBoolean("pending",false).putString("result",result).commit();busy=false;activeEngine=null;String message=result;runOnUiThread(()->{selected.clear();selectMode=false;if(!isFinishing()&&!isDestroyed()){load();if(page==null)alert("Resultado",message);}});});}
 static String mime(String name){String ext=name.contains(".")?name.substring(name.lastIndexOf('.')+1).toLowerCase(Locale.ROOT):"";String m=android.webkit.MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext);return m==null?"application/octet-stream":m;}
 void open(FileEngine.Node n,boolean share){try{Uri uri=n.uri;if(n.file!=null){String base=Environment.getExternalStorageDirectory().getCanonicalPath()+"/";String path=n.file.getCanonicalPath();if(!path.startsWith(base))throw new IOException("Local não compartilhável.");uri=new Uri.Builder().scheme("content").authority(getPackageName()+".share").appendPath("file").appendQueryParameter("path",path.substring(base.length())).build();}Intent intent=new Intent(share?Intent.ACTION_SEND:Intent.ACTION_VIEW);intent.setType(n.mime==null?mime(n.name):n.mime);if(share)intent.putExtra(Intent.EXTRA_STREAM,uri);else intent.setDataAndType(uri,n.mime==null?mime(n.name):n.mime);intent.setClipData(ClipData.newRawUri("Arquivo selecionado",uri));intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(intent,share?"Compartilhar arquivo":"Abrir com"));}catch(ActivityNotFoundException e){alert("Formato sem aplicativo","Nenhum aplicativo disponível para abrir este formato.");}catch(Exception e){error(e);}}
 static String size(long n){if(n<0)return "Tamanho desconhecido";if(n<1024)return n+" B";if(n>=1073741824L)return String.format(Locale.getDefault(),"%.1f GB",n/1073741824d);if(n<1048576)return String.format(Locale.getDefault(),"%.1f KB",n/1024d);return String.format(Locale.getDefault(),"%.1f MB",n/1048576d);}
 void help(){new RetroPages(this).help();}
 String displayPath(File file){String p=file.getAbsolutePath(),base=Environment.getExternalStorageDirectory().getAbsolutePath();return p.equals(base)?"Interno":p.startsWith(base+"/")?"Interno › "+p.substring(base.length()+1).replace("/"," › "):p;}
 void error(Exception e){alert("Não foi possível concluir",e.getMessage()==null?"Local indisponível ou operação sem suporte.":e.getMessage());}void alert(String a,String b){if(!isFinishing()&&!isDestroyed())new RetroDialog(this).setTitle(a).setMessage(b).setPositiveButton("OK",null).show();}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
